#include "vulkan_raster.hpp"
#include <iostream>
int main(){try{whj2::VulkanRaster gpu;whj2::Image source{32,32,qlie::Bytes(32*32*4)};for(unsigned y=0;y<32;y++)for(unsigned x=0;x<32;x++){auto*p=&source.pixels[(y*32+x)*4];p[0]=uint8_t(x*8);p[1]=uint8_t(y*8);p[2]=uint8_t((x+y)*4);p[3]=uint8_t((x*7+y*13)%256);}qlie::Bytes a(1280*720*4,93),b=a;whj2::RenderQueue q;for(unsigned mode=0;mode<9;mode++){auto matrix=whj2::imagePlacement(20+(mode%3)*400,20+(mode/3)*220,6,5,7,0,0,32,32);q.image(source,matrix,0,211,0x123456,0xdefabc,mode,mode%3);}q.draw(a,1280,720);gpu.begin(b);q.draw(gpu,1280,720);gpu.end(b);size_t count=0;unsigned max=0;for(size_t i=0;i<a.size();i++){unsigned d=unsigned(std::abs(int(a[i])-int(b[i])));count+=d!=0;max=std::max(max,d);}std::cout<<"BLENDS differences="<<count<<" max="<<max<<std::endl;if(count)throw std::runtime_error("GPU blend mismatch");
 a.assign(a.size(),0);b=a;whj2::RenderQueue dynamic;dynamic.snapshot(source,whj2::imagePlacement(0,0,3,3,0,0,0,32,32),0,255,0,0xffffff);dynamic.draw(a,1280,720);gpu.begin(b);dynamic.draw(gpu,1280,720);for(auto&v:source.pixels)v^=255;whj2::RenderQueue later;later.snapshot(source,whj2::imagePlacement(150,0,3,3,0,0,0,32,32),1,255,0,0xffffff);later.draw(a,1280,720);later.draw(gpu,1280,720);gpu.end(b);if(a!=b)throw std::runtime_error("GPU dynamic snapshot mismatch");std::cout<<"DYNAMIC PASS\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<std::endl;return 1;}}
